document.addEventListener('DOMContentLoaded', function() {
  // Target the TOC generated by [TOC] tag
  const toc = document.querySelector('.toc');
  if (!toc) return;
  
  // Find all list items with nested lists (only direct children)
  const topLevelItems = toc.querySelectorAll(':scope > ul > li');
  
  topLevelItems.forEach(function(item) {
    const nestedList = item.querySelector('ul');
    if (nestedList) {
      // Create wrapper for the link
      const link = item.firstChild;
      const wrapper = document.createElement('div');
      wrapper.style.display = 'flex';
      wrapper.style.alignItems = 'center';
      
      // Create toggle indicator
      const toggle = document.createElement('span');
      toggle.innerHTML = '+ ';
      toggle.style.cursor = 'pointer';
      toggle.style.marginRight = '0.5em';
      toggle.style.fontWeight = 'bold';
      toggle.style.color = 'var(--md-primary-fg-color)';
      toggle.style.userSelect = 'none';
      
      // Hide nested list by default
      nestedList.style.display = 'none';
      
      // Wrap link
      item.insertBefore(wrapper, link);
      wrapper.appendChild(toggle);
      wrapper.appendChild(link);
      
      // Toggle functionality
      toggle.addEventListener('click', function(e) {
        e.stopPropagation();
        if (nestedList.style.display === 'none') {
          nestedList.style.display = 'block';
          toggle.innerHTML = '− ';
        } else {
          nestedList.style.display = 'none';
          toggle.innerHTML = '+ ';
        }
      });
      
      // Also allow clicking the link text to expand
      link.addEventListener('click', function(e) {
        if (nestedList.style.display === 'none') {
          e.preventDefault();
          nestedList.style.display = 'block';
          toggle.innerHTML = '− ';
        }
      });
    }
  });
});